{
 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # The 2 marks the column of a ray. Extend that ray vertically through
    # the whole grid, and extend horizontally across rows containing 8s,
    # filling the gaps between their 8-pattern endpoints in color 2.
    col = next((j for i in range(h) for j in range(w) if grid[i][j] == 2), None)
    if col is None:
        return out
    for i in range(h):
        out[i][col] = 2
    for i, row in enumerate(grid):
        if 8 in row:
            # Fill the interval between the leftmost and rightmost 8 cells.
            left = row.index(8)
            right = w - 1 - row[::-1].index(8)
            for j in range(left, right + 1):
                if row[j] == 0:
                    out[i][j] = 2
    # Fill the intervening zero rows horizontally toward the span of marked
    # 8-pattern rows, from the ray column to their nearest edge.
    rows8 = [i for i,row in enumerate(grid) if 8 in row]
    if rows8:
        top, bottom = min(rows8), max(rows8)
        for i in range(top, bottom + 1):
            if 8 not in grid[i]:
                for j in range(min(col, w-1), max(col, w-1) + 1):
                    out[i][j] = 2
    return out
