 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    marker = next((i, j) for i in range(h) for j in range(w) if grid[i][j] == 2)
    rows = [i for i, row in enumerate(grid) if 8 in row]
    gaps = {i: [j for j, value in enumerate(grid[i]) if value == 0] for i in rows}
    if not rows:
        return out
    # Color the openings in every 8-bar.
    for i in rows:
        for j in gaps[i]:
            out[i][j] = 2
    # The beam above the first bar joins its openings to the source marker.
    first = rows[0]
    lo = min([marker[1]] + gaps[first])
    hi = max([marker[1]] + gaps[first])
    for j in range(lo, hi + 1):
        if grid[first - 1][j] == 0:
            out[first - 1][j] = 2
    # Connect successive bars. With one separator, bridge the next bar's
    # outer openings; with two separators, project the prior openings then
    # join them across the full row before the next bar.
    for a, b in zip(rows, rows[1:]):
        if b - a == 2:
            lo, hi = min(gaps[b]), max(gaps[b])
            for j in range(lo, hi + 1):
                if grid[a + 1][j] == 0:
                    out[a + 1][j] = 2
        elif b - a >= 3:
            for j in gaps[a]:
                if grid[a + 1][j] == 0:
                    out[a + 1][j] = 2
            for i in range(a + 2, b):
                for j in range(w):
                    if grid[i][j] == 0:
                        out[i][j] = 2
    # Continue each opening below the final bar.
    last = rows[-1]
    for i in range(last + 1, h):
        for j in gaps[last]:
            if grid[i][j] == 0:
                out[i][j] = 2
    return out
