    # Mark every interruption in each 8-line.
    for i in rows:
        for j in gaps[i]: out[i][j]=2
    # From the top marker, draw a diagonal beam into the first opening.
    first=rows[0]; g=gaps[first]
    target=min(g,key=lambda j:abs(j-mark[1]))
    for k in range(1,first-mark[0]):
        j=mark[1]+(target-mark[1])*k//(first-mark[0])
        if grid[mark[0]+k][j]==0: out[mark[0]+k][j]=2
    # Between barriers, each opening projects vertically; at separator rows
    # the projections join according to the next row's gap envelope.
    for a,b in zip(rows,rows[1:]):
        ga,gb=gaps[a],gaps[b]
        for j in ga:
            if grid[a+1][j]==0: out[a+1][j]=2
        if b-a==2:
            lo,hi=min(gb),max(gb)
            for j in range(lo,hi+1):
                if grid[a+1][j]==0: out[a+1][j]=2
        elif b-a>=3:
            for i in range(a+2,b):
                for j in range(w):
                    if grid[i][j]==0: out[i][j]=2
    # Continue last opening(s) to the bottom.
    for i in range(rows[-1]+1,h):
        for j in gaps[rows[-1]]:
            if grid[i][j]==0: out[i][j]=2
    return out
