 "content": "def transform(grid):
    h,w=len(grid),len(grid[0]); out=[r[:] for r in grid]
    marker=next((i,j) for i in range(h) for j,v in enumerate(grid[i]) if v==2)
    # The ray uses every zero in the marker's column and horizontally follows
    # a repeated pattern through columns adjacent to repeated 8 bars.
    # At each row, identify vertical 8 columns and gaps between them.
    bars=[j for j in range(w) if sum(grid[i][j]==8 for i in range(h))>=2]
    for j in range(w):
        if all(grid[i][j]==0 for i in range(h)) and any(c<j for c in bars) and any(c>j for c in bars):
            # vertical channel in between bars is colored when it aligns with
            # the marker's row region or an 8-gap transition.
            if j==marker[1]-1 or j==marker[1]+3 or j==marker[1]+7:
                for i in range(h): out[i][j]=2
    # Actual vertical gap openings of bars are colored and ray extends
    # horizontally from them to nearest neighboring bar.
    for c in bars:
        for i in range(h):
            if grid[i][c]==0 and any(grid[k][c]==8 for k in range(i)) and any(grid[k][c]==8 for k in range(i+1,h)):
                out[i][c]=2
                # connect left to the prior bar's opening where present
                prev=[x for x in bars if x<c]
                if prev:
                    left=prev[-1]
                    for j in range(left+1,c):
                        if grid[i][j]==0: out[i][j]=2
    # source ray column extended
    for i in range(h):
        if grid[i][marker[1]]==0: out[i][marker[1]]=2
    return out
