    h,w=len(grid),len(grid[0]); out=[r[:] for r in grid]
    # On each row, identify gaps in the vertical columns of color 8.
    cols=[j for j in range(w) if sum(grid[i][j]==8 for i in range(h))>=2]
    marker=next((i,j) for i in range(h) for j,v in enumerate(grid[i]) if v==2)
    # Form 2-colored rails in empty columns immediately to the left of each
    # persistent 8 column; terminate/extend at the first and last rows.
    for c in cols:
        x=c-1
        if x>=0 and all(grid[i][x]==0 for i in range(h)):
            for i in range(h):
                out[i][x]=2
    # Fill horizontal bridges where an 8-column has a missing cell, extending
    # left to the neighboring rail; also join openings to the right rail.
    rails=[j for j in range(w) if all(grid[i][j]==0 for i in range(h)) and any(c>j for c in cols)]
    for i in range(h):
        for c in cols:
            if grid[i][c]==0:
                left=max((r for r in rails if r<c),default=None)
                right=min((r for r in rails if r>c),default=None)
                if left is not None:
