{
 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # This task consists of parallel 8-bars with openings; trace the 2 path
    # through their opening positions and connect successive bars.
    bar_rows = [i for i, row in enumerate(grid) if row.count(8) >= max(2, w // 2)]
    if len(bar_rows) >= 2:
        gaps = {i: [j for j, value in enumerate(grid[i]) if value == 0] for i in bar_rows}
        marker = next(((i, j) for i in range(h) for j, value in enumerate(grid[i]) if value == 2), None)
        for i in bar_rows:
            for j in gaps[i]:
                out[i][j] = 2
        first = bar_rows[0]
        # The source ray meets the openings in the first bar.
        if first > 0 and gaps[first]:
            lo = min([marker[1]] + gaps[first]) if marker else min(gaps[first])
            hi = max([marker[1]] + gaps[first]) if marker else max(gaps[first])
            for j in range(lo, hi + 1):
                if grid[first - 1][j] == 0:
                    out[first - 1][j] = 2
        # Connect each pair of bars. A single empty row spans the openings
        # of the lower bar. A two-row separation first projects the upper
        # openings, then joins them across the field.
        for a, b in zip(bar_rows, bar_rows[1:]):
            if b - a == 2:
                if gaps[b]:
                    for j in range(min(gaps[b]), max(gaps[b]) + 1):
                        if grid[a + 1][j] == 0:
                            out[a + 1][j] = 2
            elif b - a == 3:
                for j in gaps[a]:
                    if grid[a + 1][j] == 0:
                        out[a + 1][j] = 2
                for j in range(w):
                    if grid[a + 2][j] == 0:
                        out[a + 2][j] = 2
        # Extend the openings in the last bar toward the far edge.
        last = bar_rows[-1]
        for i in range(last + 1, h):
            for j in gaps[last]:
                if grid[i][j] == 0:
                    out[i][j] = 2
        return out
    return out
