    h, w = len(grid), len(grid[0])
    # Work in a canonical orientation where the 8-stripes are horizontal.
    row_strength = max(sum(v == 8 for v in row) for row in grid)
    col_strength = max(sum(grid[i][j] == 8 for i in range(h)) for j in range(w))
    transposed = col_strength > row_strength
    src = [list(row) for row in zip(*grid)] if transposed else [row[:] for row in grid]
    H, W = len(src), len(src[0])
    out = [row[:] for row in src]
    bars = [i for i, row in enumerate(src) if sum(v == 8 for v in row) >= W // 2]
    if not bars:
        return [list(row) for row in zip(*out)] if transposed else out
    gaps = {i: [j for j, v in enumerate(src[i]) if v == 0] for i in bars}
    # Color the openings in every horizontal 8-stripe.
    for i in bars:
        for j in gaps[i]:
            out[i][j] = 2
    marker = next(((i, j) for i in range(H) for j, v in enumerate(src[i]) if v == 2), None)
    # Connect the source to the gaps in the first stripe.
    first = bars[0]
    if marker is not None and first > 0 and gaps[first]:
        lo = min([marker[1]] + gaps[first])
        hi = max([marker[1]] + gaps[first])
        for j in range(lo, hi + 1):
            if src[first - 1][j] == 0:
                out[first - 1][j] = 2
    # Between stripes, follow openings: a one-row gap spans the next stripe's
    # openings; a two-row gap projects the previous openings then joins across.
    for a, b in zip(bars, bars[1:]):
        if b - a == 2:
            if gaps[b]:
                for j in range(min(gaps[b]), max(gaps[b]) + 1):
                    if src[a + 1][j] == 0:
                        out[a + 1][j] = 2
        elif b - a == 3:
