            for j in range(W):
                if src[a + 2][j] == 0:
                    out[a + 2][j] = 2
    # Continue the final stripe's openings to the edge.
    last = bars[-1]
    for i in range(last + 1, H):
        for j in gaps[last]:
            if src[i][j] == 0:
                out[i][j] = 2
    return [list(row) for row in zip(*out)] if transposed else out
