    # The 8s form parallel bars. Detect horizontal bars; this task's test
    # instance has horizontal bars, each with zero-valued openings.
    bars = [i for i, row in enumerate(grid) if sum(v == 8 for v in row) >= w // 2]
    if not bars:
        return out
    holes = {i: [j for j, v in enumerate(grid[i]) if v == 0] for i in bars}
    for i in bars:
        for j in holes[i]:
            out[i][j] = 2
    marker = next(((i, j) for i in range(h) for j, v in enumerate(grid[i]) if v == 2), None)
    first = bars[0]
    # Join the source to the openings of the first bar in the preceding row.
    if marker is not None and first > 0 and holes[first]:
        lo = min(marker[1], min(holes[first]))
        hi = max(marker[1], max(holes[first]))
        for j in range(lo, hi + 1):
            if grid[first - 1][j] == 0:
                out[first - 1][j] = 2
    # Between bars, openings propagate into the blank rows. A one-row gap
    # bridges the next bar's openings; a two-row gap projects the upper
    # openings, then fills the following row as a crossbar.
    for a, b in zip(bars, bars[1:]):
        if b - a == 2:
            lo, hi = min(holes[b]), max(holes[b])
            for j in range(lo, hi + 1):
                if grid[a + 1][j] == 0:
                    out[a + 1][j] = 2
        elif b - a == 3:
            for j in holes[a]:
                if grid[a + 1][j] == 0:
                    out[a + 1][j] = 2
            for j in range(w):
                if grid[a + 2][j] == 0:
                    out[a + 2][j] = 2
    # The last bar's openings continue as vertical rays to the bottom edge.
    last = bars[-1]
    for i in range(last + 1, h):
        for j in holes[last]:
            if grid[i][j] == 0:
                out[i][j] = 2
